import{_ as t,c as d,o as c,a3 as o}from"./chunks/framework.czLORLkK.js";const p=JSON.parse('{"title":"SyncWatch DB 스키마 및 REST/MCP API 명세","description":"SyncWatch의 PostgreSQL 18.6 기반 6대 도메인 테이블(watch_*)과 /api/v1/watch/* 표준 REST API 및 MCP 도구 명세입니다.","frontmatter":{"title":"SyncWatch DB 스키마 및 REST/MCP API 명세","description":"SyncWatch의 PostgreSQL 18.6 기반 6대 도메인 테이블(watch_*)과 /api/v1/watch/* 표준 REST API 및 MCP 도구 명세입니다.","sidebarTitle":"DB 스키마 & API 명세","sort":4,"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/syncwatch/api-and-schema"}]]},"headers":[],"relativePath":"syncwatch/api-and-schema.md","filePath":"ko/syncwatch/api-and-schema.md","lastUpdated":1794971867000}'),a={name:"syncwatch/api-and-schema.md"};function s(r,e,l,i,n,_){return c(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="syncwatch-db-스키마-및-표준-rest-mcp-api-명세" tabindex="-1">SyncWatch DB 스키마 및 표준 REST/MCP API 명세 <a class="header-anchor" href="#syncwatch-db-스키마-및-표준-rest-mcp-api-명세" aria-label="Permalink to “SyncWatch DB 스키마 및 표준 REST/MCP API 명세”">​</a></h1><p><code>SyncWatch</code>는 전사 6-File SSOT 데이터베이스 표준(<code>sync-watch/db/00_extensions.sql</code> ~ <code>05_sample_dev.sql</code>)과 <code>/api/v1/watch/*</code> 단일 URL 매핑 원칙을 준수합니다.</p><hr><h2 id="_1-6대-핵심-도메인-테이블-watch" tabindex="-1">1. 6대 핵심 도메인 테이블 (<code>watch_*</code>) <a class="header-anchor" href="#_1-6대-핵심-도메인-테이블-watch" aria-label="Permalink to “1. 6대 핵심 도메인 테이블 (watch_*)”">​</a></h2><p><code>sync-watch/db/02_schema_domain.sql</code>에 정의된 6대 도메인 테이블은 외부 위협 수집부터 정규화, 듀얼 룰 컴파일, 샌드박스 검증, 전사 배포 이력까지 전 주기를 관리합니다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">순번</th><th style="text-align:left;">테이블명</th><th style="text-align:left;">역할 및 주요 컬럼</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td style="text-align:left;"><strong><code>watch_feed_source</code></strong></td><td style="text-align:left;"><strong>외부 보안 피드 출처 마스터</strong><br>• PK: <code>uuid</code> / UK: <code>provider_code</code><br>• 주요 컬럼: <code>provider_name</code>, <code>site_url</code>, <code>feed_url</code>, <code>feed_format</code> (<code>REST_JSON</code>, <code>YAML_NUCLEI</code> 등), <code>source_channel</code>, <code>auth_type</code>, <code>sync_interval_min</code>, <code>auto_compile_rule</code>, <code>auto_broadcast</code>, <code>enabled</code>, <code>last_sync_time</code>, <code>last_sync_status</code>, <code>last_sync_count</code>, <code>total_ingested_count</code></td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td style="text-align:left;"><strong><code>watch_security_advisory</code></strong></td><td style="text-align:left;"><strong>정규화된 보안 이슈 원장</strong><br>• PK: <code>advisory_id</code><br>• 주요 컬럼: <code>source_channel</code>, <code>feed_provider</code>, <code>external_id</code> (CVE/GHSA/KISA 번호), <code>cwe_id</code>, <code>mitre_code</code>, <code>title</code>, <code>severity</code> (<code>CRITICAL</code>, <code>HIGH</code>, <code>MEDIUM</code>, <code>LOW</code>), <code>cvss_score</code>, <code>exploit_status</code>, <code>affected_ecosystem</code>, <code>affected_packages</code>, <code>vulnerable_version_range</code>, <code>patched_version</code>, <code>summary_text</code>, <code>raw_payload_json</code> (<code>jsonb</code>), <code>matched_asset_count</code>, <code>matched_repo_count</code>, <code>compile_status</code></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td style="text-align:left;"><strong><code>watch_verse_audit_rule</code></strong></td><td style="text-align:left;"><strong>SyncVerse 공급용 보안 점검 룰 (<code>VerseAuditPack</code>)</strong><br>• PK: <code>rule_id</code> / FK: <code>advisory_id</code><br>• 주요 컬럼: <code>external_id</code>, <code>rule_title</code>, <code>severity</code>, <code>check_channel</code> (<code>SCA_DEPENDENCY</code>, <code>SAST_CODE</code>, <code>DAST_PENTEST</code>), <code>ecosystem</code>, <code>package_name</code>, <code>vulnerable_version_range</code>, <code>patched_version</code>, <code>sast_pattern_regex</code>, <code>dast_probe_method</code>, <code>dast_probe_path</code>, <code>dast_probe_payload</code>, <code>remediation_guide_md</code>, <code>target_agent_code</code>, <code>verified</code>, <code>dispatch_status</code></td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td style="text-align:left;"><strong><code>watch_apim_defense_rule</code></strong></td><td style="text-align:left;"><strong>SyncAPIM 공급용 공격 패턴 룰 (<code>ApimDefensePack</code>)</strong><br>• PK: <code>rule_id</code> / FK: <code>advisory_id</code><br>• 주요 컬럼: <code>external_id</code>, <code>rule_name</code>, <code>attack_category</code> (<code>SQLI</code>, <code>XSS</code>, <code>SSRF</code>, <code>RCE</code>, <code>PATH_TRAVERSAL</code>), <code>mitre_tactic</code>, <code>severity</code>, <code>target_locations</code> (<code>HEADER,URI,QUERY,BODY</code>), <code>target_method</code>, <code>target_path</code>, <code>detection_regex</code>, <code>defense_expression</code>, <code>grammar_fingerprint</code>, <code>positive_samples_json</code>, <code>negative_samples_json</code>, <code>sandbox_verified</code>, <code>tp_rate</code>, <code>fp_rate</code>, <code>dispatch_status</code></td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td style="text-align:left;"><strong><code>watch_dispatch_history</code></strong></td><td style="text-align:left;"><strong>전사 배포 및 적용 피드백 원장</strong><br>• PK: <code>dispatch_id</code> / FK: <code>advisory_id</code><br>• 주요 컬럼: <code>target_system</code> (<code>SYNC_VERSE</code>, <code>SYNC_APIM</code>), <code>rule_id</code>, <code>target_endpoint_url</code>, <code>dispatch_mode</code> (<code>PUSH_BROADCAST</code>, <code>PULL_SYNC</code>), <code>dispatch_status</code>, <code>response_summary</code>, <code>dispatched_by</code>, <code>dispatched_time</code>, <code>feedback_time</code></td></tr><tr><td style="text-align:center;"><strong>6</strong></td><td style="text-align:left;"><strong><code>watch_collection_job_log</code></strong></td><td style="text-align:left;"><strong>수집 배치 및 진단 문서 업로드 실행 로그</strong><br>• PK: <code>job_id</code><br>• 주요 컬럼: <code>provider_code</code>, <code>job_type</code> (<code>FEED_SYNC</code>, <code>DOC_UPLOAD</code>, <code>RULE_COMPILE</code>), <code>fetched_count</code>, <code>new_advisory_count</code>, <code>compiled_verse_rules</code>, <code>compiled_apim_rules</code>, <code>duration_ms</code>, <code>status</code>, <code>log_detail</code>, <code>executed_time</code></td></tr></tbody></table><hr><h2 id="_2-표준-rest-api-명세-api-v1-watch" tabindex="-1">2. 표준 REST API 명세 (<code>/api/v1/watch/*</code>) <a class="header-anchor" href="#_2-표준-rest-api-명세-api-v1-watch" aria-label="Permalink to “2. 표준 REST API 명세 (/api/v1/watch/*)”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">도메인 분류</th><th style="text-align:left;">HTTP Method &amp; Canonical URL</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>관측 대시보드</strong></td><td style="text-align:left;"><code>GET /api/v1/watch/overview</code></td><td style="text-align:left;">수집 피드 가동 현황, 심각도별 보안 어드바이저리 통계, 듀얼 룰 컴파일·배포 지표 조회</td></tr><tr><td style="text-align:left;"><strong>피드 출처 관리</strong></td><td style="text-align:left;"><code>GET /api/v1/watch/feeds/list</code><br><code>GET /api/v1/watch/feeds/active</code><br><code>POST /api/v1/watch/feeds/add</code><br><code>PUT /api/v1/watch/feeds/edit</code><br><code>POST /api/v1/watch/feeds/test</code><br><code>POST /api/v1/watch/feeds/sync</code></td><td style="text-align:left;">글로벌 보안 피드 출처 목록 조회·등록, 5단계 SSRF 가드 기반 연결 진단 및 즉시 동기화 실행</td></tr><tr><td style="text-align:left;"><strong>보안 어드바이저리</strong></td><td style="text-align:left;"><code>GET /api/v1/watch/advisories/list</code><br><code>GET /api/v1/watch/advisories/detail</code><br><code>POST /api/v1/watch/advisories/register</code><br><code>POST /api/v1/watch/advisories/upload</code><br><code>POST /api/v1/watch/advisories/compile</code><br><code>POST /api/v1/watch/advisories/match-sbom</code></td><td style="text-align:left;">정규화된 보안 이슈 원장 검색, 보안 진단 문서·번들 업로드 파싱, 듀얼 룰 컴파일 및 전사 SBOM 의존성 교차 매칭</td></tr><tr><td style="text-align:left;"><strong>듀얼 룰 &amp; 샌드박스</strong></td><td style="text-align:left;"><code>GET /api/v1/watch/verse-rules/list</code><br><code>PUT /api/v1/watch/verse-rules/edit</code><br><code>GET /api/v1/watch/apim-rules/list</code><br><code>PUT /api/v1/watch/apim-rules/edit</code><br><code>POST /api/v1/watch/apim-rules/verify-sandbox</code></td><td style="text-align:left;"><code>VerseAuditPack</code> 점검 룰 및 <code>ApimDefensePack</code> 방어 룰 조회·편집, Positive/Negative 샘플 기반 샌드박스 검증</td></tr><tr><td style="text-align:left;"><strong>보안 팩 &amp; 전사 배포</strong></td><td style="text-align:left;"><code>GET /api/v1/watch/packs/verse</code><br><code>GET /api/v1/watch/packs/apim</code><br><code>POST /api/v1/watch/dispatch/broadcast</code><br><code>POST /api/v1/watch/dispatch/feedback</code><br><code>GET /api/v1/watch/dispatches/list</code><br><code>GET /api/v1/watch/dispatches/jobs</code></td><td style="text-align:left;"><code>SyncVerse</code> 및 <code>SyncAPIM</code>용 보안 팩 조회(Pull), 실시간 브로드캐스트 배포(Push), 적용 피드백 수신 및 작업 로그 조회</td></tr><tr><td style="text-align:left;"><strong>MCP 서버 &amp; 메뉴 인가</strong></td><td style="text-align:left;"><code>GET /api/v1/watch/mcp/tools</code><br><code>POST /api/v1/watch/mcp</code><br><code>GET /api/v1/watch/sys/permission/getUserPermissionByToken</code></td><td style="text-align:left;">JSON-RPC 2.0 MCP 도구 목록·실행 및 현재 인증 사용자의 역할(<code>role_admin</code>, <code>role_secops</code>) 동적 메뉴 트리 반환</td></tr></tbody></table><hr><h2 id="_3-mcp-model-context-protocol-노출-도구-명세-api-v1-watch-mcp" tabindex="-1">3. MCP (Model Context Protocol) 노출 도구 명세 (<code>/api/v1/watch/mcp</code>) <a class="header-anchor" href="#_3-mcp-model-context-protocol-노출-도구-명세-api-v1-watch-mcp" aria-label="Permalink to “3. MCP (Model Context Protocol) 노출 도구 명세 (/api/v1/watch/mcp)”">​</a></h2><p><code>SyncWatch</code>는 타 에이전트(<code>SyncVerse</code>, <code>SyncAPIM</code>, <code>SyncInsight</code>)가 A2A 프로토콜로 위협 인텔리전스를 즉시 조회하거나 룰 컴파일·배포를 트리거할 수 있도록 표준 MCP 도구를 노출합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">MCP 도구명</th><th style="text-align:left;">주요 파라미터</th><th style="text-align:left;">기능 설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>watch_sync_security_feeds</code></strong></td><td style="text-align:left;"><code>providerCode</code> (선택)</td><td style="text-align:left;">외부 보안 피드(OSV, GHSA, NVD, CISA KEV, Nuclei, OWASP, MITRE, KISA) 동기화 및 정규화 실행</td></tr><tr><td style="text-align:left;"><strong><code>watch_compile_dual_rules</code></strong></td><td style="text-align:left;"><code>advisoryId</code></td><td style="text-align:left;">단일 보안 이슈로부터 <code>SyncVerse</code> 점검 룰(<code>VerseAuditPack</code>) 및 <code>SyncAPIM</code> 공격 패턴(<code>ApimDefensePack</code>)을 동시 컴파일하고 샌드박스 검증 실행</td></tr><tr><td style="text-align:left;"><strong><code>watch_dispatch_to_verse_and_apim</code></strong></td><td style="text-align:left;"><code>advisoryId</code>, <code>targetSystem</code></td><td style="text-align:left;">검증 완료된 보안 점검 룰 및 WAF 가상 패치 룰을 <code>SyncVerse</code>와 <code>SyncAPIM</code>으로 즉시 브로드캐스트 배포</td></tr><tr><td style="text-align:left;"><strong><code>watch_match_enterprise_sbom</code></strong></td><td style="text-align:left;"><code>ecosystem</code> (선택)</td><td style="text-align:left;">전사 마이크로서비스 SBOM 패키지와 취약점 원장을 교차 매칭하여 영향 자산·리포지토리 산출</td></tr><tr><td style="text-align:left;"><strong><code>delegate_intent</code></strong></td><td style="text-align:left;"><code>intent</code>, <code>instruction</code></td><td style="text-align:left;">A2A 자연어 보안 인텔리전스 수집·컴파일·전사 배포 위임 실행</td></tr></tbody></table>',13)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
